#!/usr/bin/env bun
/**
 * Every generated file names a writer that exists. ADVISORY: it warns and
 * exits 0 (`--strict` exits 1).
 *
 * @covers none — a marker audit over committed and built files; judges no graph
 *
 * ## Derive, accept all, warn
 *
 * - **No list of generators here.** A writer is real when the checkout can
 *   find it: a script file at the path the marker names (from the file's own
 *   directory up to the checkout root, or from any layer root), or a task
 *   in the script table (`bun run cat <task>`).
 * - **All four markers are accepted**, as they are written today: a top-level
 *   `_generated` in JSON, `generated:` front matter, a `$schema` the graph-kind
 *   registry flags `generated: true`, and an HTML comment banner saying
 *   "generated by". The registry flag names no writer, so a file carrying it
 *   passes on the flag alone.
 * - **Warn only.** A marker that names no writer, or one the checkout cannot
 *   find, is printed, and the run exits 0.
 *
 * ## Unmarked files, where a writer declares what it writes
 *
 * A generated file with NO marker is found through the `writes` declaration:
 * each writer task lists the committed files it writes (`task-io.ts`'s
 * `OWN_WRITES`, or a layer's `taskIo.<task>.writes`). Every file a glob
 * matches must carry a marker, and a glob that matches nothing is reported
 * too. A writer that declares nothing is not checked for unmarked files.
 *
 *   bun run cat check:generated-writers [--strict]
 */

import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { instanceRootsIn } from "../schemas/kg/cat-harness.ts";
import { defaultGraphTypologies } from "../schemas/kg/graph-typology-registry.ts";
import { scriptTable } from "../schemas/sdlc/script-table.ts";
import { readDeclaration } from "../schemas/kg/cat-harness.ts";
import { collectTaskWrites, type TaskWrites } from "./task-io.ts";

const REPO = resolve(import.meta.dir, "../..");

/** The files a marker can be read from; anything bigger is data, not a page. */
const SCANNED = /\.(json|jsonld|md|html)$/;
const MAX_BYTES = 4 * 1024 * 1024;
const SKIP_DIRS = new Set(["node_modules", "_site", "_kg", "test-results"]);

export type MarkerKind = "_generated" | "front-matter" | "registry" | "html-banner" | "none";

export interface Marker {
  kind: MarkerKind;
  /** The marker's text, where it has one (the registry flag has none). */
  text?: string;
}

/** `$schema` values the registry flags `generated: true`, read from the declared kinds. */
export function generatedSchemas(): ReadonlySet<string> {
  const out = new Set<string>();
  for (const name of defaultGraphTypologies.names()) {
    for (const [schema, d] of Object.entries(defaultGraphTypologies.get(name)?.nodeSchemas ?? {})) {
      if ((d as { generated?: unknown }).generated === true) out.add(schema);
    }
  }
  return out;
}

/** The marker a file's own text carries, or `undefined`. */
export function markerOf(name: string, text: string, registry: ReadonlySet<string>): Marker | undefined {
  if (/\.(json|jsonld)$/.test(name)) {
    let top: unknown;
    try {
      top = JSON.parse(text);
    } catch {
      return undefined;
    }
    if (typeof top !== "object" || top === null || Array.isArray(top)) return undefined;
    const t = top as Record<string, unknown>;
    if (typeof t._generated === "string") return { kind: "_generated", text: t._generated };
    if (t._generated !== undefined) return { kind: "_generated", text: JSON.stringify(t._generated) };
    if (typeof t.$schema === "string" && registry.has(t.$schema)) return { kind: "registry" };
    return undefined;
  }
  const head = text.slice(0, 4000);
  const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(head);
  const gen = fm ? /^generated:\s*(.+)$/m.exec(fm[1]!) : null;
  if (gen) return { kind: "front-matter", text: gen[1]!.trim().replace(/^["']|["']$/g, "") };
  const banner = /<!--([^]*?generated by[^]*?)-->/i.exec(head);
  if (banner) return { kind: "html-banner", text: banner[1]!.trim() };
  return undefined;
}

/** The writers a marker's text names: script paths and `bun run cat <task>` tasks. */
export function writersNamed(text: string): { paths: string[]; tasks: string[] } {
  const paths = [...text.matchAll(/(?:^|[\s`(])((?:[\w.@-]+\/)*[\w.@-]+\.(?:ts|mjs|js|py|sh))\b/g)].map((m) => m[1]!);
  const tasks = [...text.matchAll(/bun run cat ([\w:.-]+)/g)].map((m) => m[1]!);
  return { paths: [...new Set(paths)], tasks: [...new Set(tasks)] };
}

export interface Finding {
  file: string;
  kind: MarkerKind;
  problem: string;
}

/**
 * Judge one marker. `roots` are the layer roots; a path resolves from the
 * file's directory and each directory above it up to `repo`, or from a root.
 */
export function judge(abs: string, m: Marker, o: { repo: string; roots: readonly string[]; tasks: ReadonlySet<string> }): string | undefined {
  if (m.kind === "registry") return undefined;
  const { paths, tasks } = writersNamed(m.text ?? "");
  if (paths.length === 0 && tasks.length === 0) return "the marker names no writer (no script path, no `bun run cat` task)";
  const bases: string[] = [];
  for (let d = dirname(abs); ; d = dirname(d)) {
    bases.push(d);
    if (d === o.repo || !d.startsWith(o.repo + sep) || dirname(d) === d) break;
  }
  bases.push(...o.roots);
  const missingPaths = paths.filter((p) => !bases.some((b) => existsSync(join(b, p))));
  const missingTasks = tasks.filter((t) => !o.tasks.has(t));
  // One real writer is enough: a marker often names the script AND its task.
  if (missingPaths.length < paths.length || missingTasks.length < tasks.length) return undefined;
  return `names a writer the checkout does not have: ${[...missingPaths, ...missingTasks.map((t) => `bun run cat ${t}`)].join(", ")}`;
}

/**
 * Files a declared `writes` glob matches that carry no marker, and globs that
 * match nothing. `byName` resolves an `<instance>:` prefix to its root.
 */
export function unmarkedWrites(
  writes: readonly TaskWrites[],
  o: { repo: string; byName: ReadonlyMap<string, string>; registry: ReadonlySet<string> },
): Finding[] {
  const out: Finding[] = [];
  for (const w of writes) {
    for (const g of w.globs) {
      const m = /^([a-z0-9][a-z0-9-]*):(.+)$/.exec(g);
      const base = m ? o.byName.get(m[1]!) : w.instance;
      const pattern = m ? m[2]! : g;
      if (base === undefined) {
        out.push({ file: g, kind: "none", problem: `\`${w.task}\` declares writes in instance \`${m![1]}\`, which is not in this checkout` });
        continue;
      }
      const files = [...new Bun.Glob(pattern).scanSync({ cwd: base, onlyFiles: true })].sort();
      if (files.length === 0) {
        out.push({ file: relative(o.repo, join(base, pattern)), kind: "none", problem: `\`${w.task}\` declares writes that match no file` });
        continue;
      }
      for (const f of files) {
        const abs = join(base, f);
        if (markerOf(abs, readFileSync(abs, "utf-8"), o.registry) === undefined) {
          out.push({ file: relative(o.repo, abs), kind: "none", problem: `written by \`${w.task}\` (its declared writes) but carries no generated marker` });
        }
      }
    }
  }
  return out;
}

function* filesUnder(dir: string): Generator<string> {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const e of entries) {
    if (e.name.startsWith(".") || SKIP_DIRS.has(e.name)) continue;
    const p = join(dir, e.name);
    if (e.isDirectory()) yield* filesUnder(p);
    else if (e.isFile() && SCANNED.test(e.name)) yield p;
  }
}

export function audit(repo: string = REPO): { scanned: number; marked: Record<Exclude<MarkerKind, "none">, number>; findings: Finding[] } {
  const roots = instanceRootsIn(repo).map((r) => resolve(r));
  const tasks = new Set(scriptTable(repo).keys());
  const registry = generatedSchemas();
  const seen = new Set<string>();
  const marked: Record<Exclude<MarkerKind, "none">, number> = { _generated: 0, "front-matter": 0, registry: 0, "html-banner": 0 };
  const findings: Finding[] = [];
  for (const root of roots) {
    for (const abs of filesUnder(root)) {
      if (seen.has(abs)) continue;
      seen.add(abs);
      if (statSync(abs).size > MAX_BYTES) continue;
      const m = markerOf(abs, readFileSync(abs, "utf-8"), registry);
      if (m === undefined) continue;
      marked[m.kind as Exclude<MarkerKind, "none">]++;
      const problem = judge(abs, m, { repo: resolve(repo), roots, tasks });
      if (problem) findings.push({ file: relative(repo, abs), kind: m.kind, problem });
    }
  }
  const byName = new Map<string, string>();
  for (const r of roots) {
    const name = readDeclaration(r)?.name;
    if (name !== undefined && !byName.has(name)) byName.set(name, r);
  }
  findings.push(...unmarkedWrites(collectTaskWrites(repo), { repo, byName, registry }));
  findings.sort((a, b) => a.file.localeCompare(b.file));
  return { scanned: seen.size, marked, findings };
}

if (import.meta.main) {
  const strict = process.argv.includes("--strict");
  const { scanned, marked, findings } = audit();
  const total = Object.values(marked).reduce((a, b) => a + b, 0);
  console.log(
    `check:generated-writers: ${scanned} file(s) scanned, ${total} carry a generated marker ` +
      `(${Object.entries(marked).map(([k, n]) => `${k} ${n}`).join(", ")})`,
  );
  // One line per (problem), with its files counted: a stale writer is usually
  // named by every file it wrote.
  const byProblem = new Map<string, Finding[]>();
  for (const f of findings) byProblem.set(f.problem, [...(byProblem.get(f.problem) ?? []), f]);
  for (const [problem, fs] of byProblem) {
    console.log(`  ⚠ ${fs.length} file(s): ${problem}`);
    for (const f of fs.slice(0, 3)) console.log(`      ${f.file} (${f.kind})`);
    if (fs.length > 3) console.log(`      … and ${fs.length - 3} more`);
  }
  if (findings.length === 0) console.log("  ✓ every marker names a writer the checkout has");
  else console.log(`  ${findings.length} warning(s). Advisory (folio-assistant#1254): fix the marker or the writer; --strict fails on them.`);
  process.exit(strict && findings.length > 0 ? 1 : 0);
}
